-- Candidate only: review and test with actual dispatcher credential before deployment.
-- Preserve existing requester partition and terminal-state permissions.
BEGIN;
SET LOCAL lock_timeout = '3s';
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='glorifier_autopilot_missions' AND policyname='digital_me_dispatcher_scope' AND with_check=$policy$((requester = 'github:32674233'::text) AND (id ~ '^mission-coding-[a-f0-9]{64}$'::text) AND (idempotency_key ~ '^github:GLORIFIER7/GLORIFIER:comment:[1-9][0-9]{0,15}$'::text) AND ((payload ->> 'title'::text) = 'GitHub fix #471'::text) AND ((payload ->> 'id'::text) = id) AND ((payload ->> 'requester'::text) = requester) AND ((payload ->> 'idempotencyKey'::text) = idempotency_key) AND ((payload ->> 'status'::text) = status) AND ((payload ->> 'version'::text) = (version)::text) AND (status = ANY (ARRAY['blocked'::text, 'failed'::text, 'completed'::text, 'reconciliation-required'::text])))$policy$) THEN
 RAISE EXCEPTION 'Dispatcher policy differs from reviewed baseline';
 END IF;
END $$;
ALTER POLICY digital_me_dispatcher_scope ON public.glorifier_autopilot_missions
WITH CHECK (((requester = 'github:32674233'::text) AND (id ~ '^mission-coding-[a-f0-9]{64}$'::text) AND (idempotency_key ~ '^github:GLORIFIER7/GLORIFIER:comment:[1-9][0-9]{0,15}$'::text) AND ((payload ->> 'title'::text) = 'GitHub fix #471'::text) AND ((payload ->> 'id'::text) = id) AND ((payload ->> 'requester'::text) = requester) AND ((payload ->> 'idempotencyKey'::text) = idempotency_key) AND ((payload ->> 'status'::text) = status) AND ((payload ->> 'version'::text) = (version)::text) AND ((status = ANY (ARRAY['blocked'::text, 'failed'::text, 'completed'::text, 'reconciliation-required'::text])) OR (status = 'executing' AND lease_owner ~ '^[a-zA-Z0-9][a-zA-Z0-9_-]{0,127}$' AND lease_expires_at > statement_timestamp() AND lease_expires_at <= statement_timestamp() + interval '305 seconds' AND payload->>'leaseOwner' = lease_owner AND (payload->>'leaseExpiresAt')::timestamptz = lease_expires_at AND payload->'dispatcher'->>'phase' IN ('preparing','publishing') AND payload->'dispatcher'->>'attempts' IN ('1','2') AND payload->'dispatcher'->>'base' ~ '^[a-f0-9]{40}$' AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'base' = payload->'dispatcher'->>'base' AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'recipeId' = payload->'dispatcher'->>'recipeId' AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'delegationId' = payload->'dispatcher'->>'grantId' AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'contextId' = id AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'repository' = 'GLORIFIER7/GLORIFIER' AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'delegator' = requester AND (public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'principal' = 'digital-me' AND ((public.read_digital_me_dispatcher_grant(id, payload->'dispatcher'->>'base'))->>'expiresAt')::timestamptz > statement_timestamp()))));
COMMIT;
